    private void ui(Runnable r){AtomicReference<Throwable> e=new AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable t){e.set(t);}});if(e.get()!=null)throw new RuntimeException(e.get());waitForIdleSync();}
    private void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
    private void collect(View v,List<String> out){if(v instanceof TextView)out.add(((TextView)v).getText().toString());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)collect(((ViewGroup)v).getChildAt(i),out);}
    private TextView containing(View v,String value){if(v instanceof TextView&&((TextView)v).getText().toString().contains(value))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView found=containing(((ViewGroup)v).getChildAt(i),value);if(found!=null)return found;}return null;}
    private List<String> texts(Activity a){List<String> out=new ArrayList<>();collect(a.getWindow().getDecorView(),out);return out;}
    private List<String> windowTexts(){List<String> out=new ArrayList<>();for(View root:android.view.inspector.WindowInspector.getGlobalWindowViews())if(root.isShown())collect(root,out);return out;}
    private void install(String id)throws Exception{try(InputStream in=new FileInputStream("/data/local/tmp/internal-apps/"+id+".ddapp")){call(apps,"install",new Class[]{InputStream.class,String.class,String.class},in,id,null);}}
    private Activity open(String id)throws Exception{Intent intent=(Intent)type("ModuleRuntime").getMethod("pageIntent",Context.class,String.class,String.class).invoke(null,host,id,"main");Activity a=startActivitySync(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();return a;}
    private void await(java.util.function.BooleanSupplier condition,String label)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);check(condition.getAsBoolean(),label);}
    private TextView homeButton(View v,String label){
        if(v instanceof TextView && label.contentEquals(((TextView)v).getText()) && v.isClickable())return (TextView)v;
        if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView found=homeButton(g.getChildAt(i),label);if(found!=null)return found;}}
        return null;
    }
    private boolean hasText(View v,String label){if(v instanceof TextView&&label.contentEquals(((TextView)v).getText()))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(hasText(((ViewGroup)v).getChildAt(i),label))return true;return false;}
    private ScrollView scrollContaining(View v,String label){if(v instanceof ScrollView&&hasText(v,label))return (ScrollView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){ScrollView found=scrollContaining(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}    private int[] desktopEdges(Activity a,String label)throws Exception{
        waitForIdleSync();
        TextView home=homeButton(a.getWindow().getDecorView(),label);
        check(home!=null&&home.isShown(),"desktop action is visible");
        int[] pos=new int[2];home.getLocationOnScreen(pos);
        float density=a.getResources().getDisplayMetrics().density;
        int[] edges={pos[0],pos[0]+home.getWidth(),home.getHeight()};
        int screenWidth=a.getWindow().getDecorView().getWidth();
        int horizontalInset=Math.round(18*density),minimumHeight=Math.round(52*density);
        check(edges[0]>=horizontalInset&&screenWidth-edges[1]>=horizontalInset&&edges[1]-edges[0]>=screenWidth-2*horizontalInset&&edges[2]>=minimumHeight,"measured settings-style desktop width and height: "+Arrays.toString(edges));
        android.util.Log.i("DesktopEdges",a.getLocalClassName()+" "+Arrays.toString(edges));
        return edges;
    }
