        File archive=(File)call(type("InternalDataBackup"),"exportData",new Class[]{Context.class,byte[].class},c,bytes);check(archive.length()>0,"full data archive written");String manifest;try(java.util.zip.ZipFile zip=new java.util.zip.ZipFile(archive);InputStream in=zip.getInputStream(zip.getEntry("internal.json"));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] chunk=new byte[4096];int n;while((n=in.read(chunk))!=-1)out.write(chunk,0,n);manifest=new String(out.toByteArray(),"UTF-8");}JSONArray exportedApps=new JSONObject(manifest).getJSONArray("apps");android.util.Log.i("InternalAppsUiTests","exported data sets="+exportedApps.length()+" ids="+call(type("AppModules"),"allIds",new Class[]{}));check(exportedApps.length()==11,"full data archive includes all 11 internal apps");p.edit().putInt("volume_percent",88).commit();Files.write(sample.toPath(),"changed".getBytes("UTF-8"));Object prepared=call(type("InternalDataBackup"),"read",new Class[]{Context.class,Uri.class},c,Uri.fromFile(archive));call(prepared,"apply",new Class[]{Context.class},c);check((Boolean)call(prepared,"finish",new Class[]{Context.class,boolean.class},c,true),"archive commit");check(p.getInt("volume_percent",0)==17,"music settings restored");check(new String(Files.readAllBytes(sample.toPath()),"UTF-8").equals("archive-data"),"module file restored");
        p.edit().putInt("volume_percent",44).commit();Files.write(sample.toPath(),"before-rollback".getBytes("UTF-8"));Object rollback=call(type("InternalDataBackup"),"read",new Class[]{Context.class,Uri.class},c,Uri.fromFile(archive));call(rollback,"apply",new Class[]{Context.class},c);check((Boolean)call(rollback,"finish",new Class[]{Context.class,boolean.class},c,false),"archive rollback completes");check(p.getInt("volume_percent",0)==44&&new String(Files.readAllBytes(sample.toPath()),"UTF-8").equals("before-rollback"),"files and preferences rolled back together");
